  "outcome": "deny",
  "rationale": "We are denying this claim because the claimant's account explicitly states that the collision was caused intentionally. Under the policy exclusion for intentional acts, losses caused deliberately by an insured person are not covered.",
  "citations": [
    {
      "clause_id": "PLUS-4.3",
      "quote": "We do not cover loss caused intentionally by, or at the direction of, an insured person."
    }
  ]
}
